type KhmerSegment = {
  length: number;
  type: 'invalid' | 'repeat' | 'valid';
  word: string;
};

const LONG_VALID_SEGMENT_LENGTH = 3;

function isCombiningMark(character: string) {
  return /\p{M}/u.test(character);
}

function findLongestValidWord(
  characters: string[],
  startIndex: number,
  isValidWord: (word: string) => boolean,
) {
  const characterCount = characters.length;
  let longestMatch: { length: number; word: string } | null = null;

  for (let length = 1; length <= characterCount - startIndex; length += 1) {
    const word = characters.slice(startIndex, startIndex + length).join('');
    const nextIndex = startIndex + length;

    if (nextIndex < characterCount && isCombiningMark(characters[nextIndex])) {
      continue;
    }

    if (length === 1) {
      const nextCharacterHasMark =
        nextIndex < characterCount &&
        nextIndex + 1 < characterCount &&
        isCombiningMark(characters[nextIndex + 1]);

      if (nextCharacterHasMark) {
        continue;
      }
    }

    if (isValidWord(word)) {
      longestMatch = { length, word };
    }
  }

  return longestMatch;
}

function segmentKhmerWord(
  word: string,
  isValidWord: (segment: string) => boolean,
) {
  const characters = Array.from(String(word || ''));
  if (!characters.length) {
    return [];
  }

  const rawSegments: KhmerSegment[] = [];
  let index = 0;

  while (index < characters.length) {
    const validWord = findLongestValidWord(characters, index, isValidWord);

    if (validWord) {
      if (
        validWord.length === 1 &&
        index + 1 < characters.length &&
        characters[index + 1] === characters[index]
      ) {
        let repeatCount = 1;

        while (
          index + repeatCount < characters.length &&
          characters[index + repeatCount] === characters[index]
        ) {
          repeatCount += 1;
        }

        rawSegments.push({
          length: repeatCount,
          type: 'repeat',
          word: characters.slice(index, index + repeatCount).join(''),
        });
        index += repeatCount;
        continue;
      }

      rawSegments.push({
        length: validWord.length,
        type: 'valid',
        word: validWord.word,
      });
      index += validWord.length;
      continue;
    }

    let repeatCount = 1;
    const currentCharacter = characters[index];

    while (
      index + repeatCount < characters.length &&
      characters[index + repeatCount] === currentCharacter
    ) {
      repeatCount += 1;
    }

    if (repeatCount >= 2) {
      rawSegments.push({
        length: repeatCount,
        type: 'repeat',
        word: characters.slice(index, index + repeatCount).join(''),
      });
      index += repeatCount;
      continue;
    }

    rawSegments.push({
      length: 1,
      type: 'invalid',
      word: currentCharacter,
    });
    index += 1;
  }

  const segments: string[] = [];
  let rawIndex = 0;

  while (rawIndex < rawSegments.length) {
    const segment = rawSegments[rawIndex];

    if (segment.type === 'valid') {
      segments.push(segment.word);
      rawIndex += 1;
      continue;
    }

    const accumulated = [segment.word];
    let lookAheadIndex = rawIndex + 1;

    while (lookAheadIndex < rawSegments.length) {
      const lookAheadSegment = rawSegments[lookAheadIndex];

      if (
        lookAheadSegment.type === 'valid' &&
        lookAheadSegment.length >= LONG_VALID_SEGMENT_LENGTH
      ) {
        break;
      }

      accumulated.push(lookAheadSegment.word);
      lookAheadIndex += 1;
    }

    segments.push(accumulated.join(''));
    rawIndex = lookAheadIndex;
  }

  return segments;
}

function getKhmerSegmentationSegments(
  word: string,
  isValidWord: (segment: string) => boolean,
) {
  const normalizedWord = String(word || '');
  if (!normalizedWord) {
    return [];
  }

  const segments = segmentKhmerWord(normalizedWord, isValidWord);
  if (segments.length < 2 || segments.join('') !== normalizedWord) {
    return [];
  }

  return segments;
}

export { getKhmerSegmentationSegments };
